<?php
function normalize_brand($raw) {
 return array('id'=>isset($raw['id']) ? $raw['id'] : generate_uuid(), 'name'=>clean_content_text(arr_get($raw,'name','')), 'thumbnail'=>clean_content_text(arr_get($raw,'thumbnail','')), 'order'=>isset($raw['order']) ? intval($raw['order']) : 0);
}
function create_brand() { require_auth(); $input=get_json_input(); if (!trim(arr_get($input,'name','')) || !trim(arr_get($input,'thumbnail',''))) send_error('Brand name and thumbnail are required'); $data=json_read('projects.json'); $brands=arr_get($data,'brands',array()); $brand=normalize_brand($input); $brand['order']=count($brands); $brands[]=$brand; $data['brands']=$brands; json_write('projects.json',$data); send_json($brand); }
function update_brand($id) { require_auth(); $input=get_json_input(); $data=json_read('projects.json'); $found=false; foreach($data['brands'] as $i=>$b) if((string)$b['id']===(string)$id){$data['brands'][$i]=normalize_brand(array_merge($b,$input));$found=true;$result=$data['brands'][$i];} if(!$found) send_error('Brand not found',404); json_write('projects.json',$data);send_json($result); }
function delete_brand($id) { require_auth(); $data=json_read('projects.json'); $data['brands']=array_values(array_filter(arr_get($data,'brands',array()),function($b)use($id){return (string)$b['id'] !== (string)$id;})); foreach($data['projects'] as &$p)if((string)arr_get($p,'brand','')===(string)$id)$p['brand']=''; unset($p);json_write('projects.json',$data);send_json(array('success'=>true)); }
